# Simulasi Struktur Metadata Hierarkis: Delta Lake Commit Log vs Apache Iceberg Snapshot Tree
class OpenTableFormatSimulator:
    @staticmethod
    def simulate_delta_log():
        # Delta Lake: Sequential Commit Log files
        log_commits = [
            {'commit_id': 0, 'add_files': ['part-01.parquet', 'part-02.parquet'], 'remove_files': []},
            {'commit_id': 1, 'add_files': ['part-03.parquet'], 'remove_files': ['part-01.parquet']},
        ]
        # State rekonstruksi aktif
        active_files = set()
        for c in log_commits:
            for add_f in c['add_files']:
                active_files.add(add_f)
            for rem_f in c['remove_files']:
                active_files.remove(rem_f)
        return {'format': 'Delta Lake', 'commits': len(log_commits), 'active_files': sorted(list(active_files))}

    @staticmethod
    def simulate_iceberg_tree():
        # Iceberg: Hierarki Metadata -> Manifest List -> Manifest File -> Data Files
        snapshot_tree = {
            'snapshot_id': 1024,
            'manifest_list': 'snap-1024.avro',
            'manifests': [
                {'manifest_name': 'm1.avro', 'data_files': ['part-02.parquet', 'part-03.parquet']}
            ]
        }
        active_files = []
        for m in snapshot_tree['manifests']:
            active_files.extend(m['data_files'])
        return {'format': 'Apache Iceberg', 'snapshot_id': snapshot_tree['snapshot_id'], 'active_files': sorted(active_files)}

delta_res = OpenTableFormatSimulator.simulate_delta_log()
iceberg_res = OpenTableFormatSimulator.simulate_iceberg_tree()

print('Inspeksi Metadata Format Tabel Terbuka:')
print(f'  1. {delta_res["format"]}:')
print(f'     - Mekanisme: Berurutan JSON Commit Logs ({delta_res["commits"]} commits dievaluasi)')
print(f'     - File Data Aktif Terpilih: {delta_res["active_files"]}')
print(f'  2. {iceberg_res["format"]}:')
print(f'     - Mekanisme: Pohon Hierarki Snapshot (Snapshot ID {iceberg_res["snapshot_id"]})')
print(f'     - File Data Aktif Terpilih: {iceberg_res["active_files"]}')
print('  Hasil: Kedua arsitektur berhasil mengisolasi file data aktif secara deterministik!')

# Implementasi Simulator Optimistic Concurrency Control (OCC) pada Lakehouse Transaction Log
class OptimisticTransactionCoordinator:
    def __init__(self):
        self.current_version = 0
        self.commit_history = {}

    def begin_transaction(self):
        return {'read_version': self.current_version}

    def commit_transaction(self, txn, added_files, modified_partitions):
        read_ver = txn['read_version']
        target_ver = self.current_version + 1

        # Deteksi apakah terjadi commit konkuren selama masa eksekusi transaksi
        if read_ver < self.current_version:
            # Validasi apakah terjadi konflik partisi langsung dengan commit perantara
            for past_v in range(read_ver + 1, self.current_version + 1):
                past_commit = self.commit_history[past_v]
                conflict_partitions = set(modified_partitions).intersection(set(past_commit['partitions']))
                if conflict_partitions:
                    return {'status': 'ABORTED_CONFLICT', 'conflict_on': list(conflict_partitions)}
            # Jika partisi tidak beririsan: Auto-rebase diizinkan!

        # Commit sukses: Tetapkan versi baru secara atomik
        self.current_version = target_ver
        self.commit_history[target_ver] = {
            'files': added_files,
            'partitions': modified_partitions
        }
        return {'status': 'COMMITTED', 'version': target_ver}

coord = OptimisticTransactionCoordinator()

# Inisialisasi: Transaksi 1 dan Transaksi 2 membaca state yang sama (Version 0)
tx1 = coord.begin_transaction()
tx2 = coord.begin_transaction()

# Transaksi 1 memodifikasi partisi 'region=US'
res1 = coord.commit_transaction(tx1, added_files=['us-01.parquet'], modified_partitions=['region=US'])

# Transaksi 2 memodifikasi partisi 'region=EU' (Tidak beririsan -> Auto-rebase sukses!)
res2 = coord.commit_transaction(tx2, added_files=['eu-01.parquet'], modified_partitions=['region=EU'])

print('Evaluasi Eksekusi Transaksi Berbasis OCC Transaction Log:')
print(f'  Transaksi 1: Status={res1["status"]} -> Versi Terpasang: {res1.get("version")}')
print(f'  Transaksi 2: Status={res2["status"]} -> Versi Terpasang: {res2.get("version")} (Auto-rebase sukses!)')
print(f'  Versi Akhir Tabel Lakehouse: {coord.current_version} (Konsistensi Terjamin)')

# Implementasi Simulator Schema Enforcement & Schema Evolution pada Delta Lake
class DeltaSchemaGuard:
    def __init__(self, initial_schema):
        # Skema tabel terdaftar: {nama_kolom: tipe_data}
        self.table_schema = initial_schema.copy()

    def write_dataset(self, data_records, record_schema, merge_schema=False):
        # Periksa apakah ada kolom tambahan yang belum ada di tabel
        extra_cols = set(record_schema.keys()) - set(self.table_schema.keys())

        if extra_cols and not merge_schema:
            # Schema Enforcement: Lempar exception penolakan
            return {
                'status': 'REJECTED',
                'error': f'SchemaEnforcementError: Kolom asing terdeteksi: {extra_cols}. Write ditolak!',
                'records_written': 0
            }

        if extra_cols and merge_schema:
            # Schema Evolution: Perbarui skema tabel resmi
            for col in extra_cols:
                self.table_schema[col] = record_schema[col]

        return {
            'status': 'SUCCESS',
            'active_schema': self.table_schema.copy(),
            'records_written': len(data_records)
        }

base_schema = {'order_id': 'int', 'amount': 'float'}
guard = DeltaSchemaGuard(initial_schema=base_schema)

# Kasus 1: Penulisan batch dengan kolom tak terduga tanpa izin mergeSchema
bad_batch = [{'order_id': 1, 'amount': 150.0, 'unknown_promo_col': 'VIP_DISC'}]
bad_schema = {'order_id': 'int', 'amount': 'float', 'unknown_promo_col': 'string'}
res_rejected = guard.write_dataset(bad_batch, bad_schema, merge_schema=False)

# Kasus 2: Penulisan dengan kolom baru yang disetujui secara eksplisit (merge_schema=True)
res_evolved = guard.write_dataset(bad_batch, bad_schema, merge_schema=True)

print('Evaluasi Keamanan Skema Delta Lake:')
print(f'  [Uji 1 - Schema Enforcement] : Status={res_rejected["status"]}')
print(f'     Pesan Penolakan          : {res_rejected["error"]}')
print(f'  [Uji 2 - Schema Evolution]   : Status={res_evolved["status"]}')
print(f'     Skema Hasil Evolusi Resmi: {res_evolved["active_schema"]}')
print('  Kesimpulan: Schema guard menjaga integritas data lakehouse dari pencemaran anomali.')

# Implementasi Pipeline Lengkap Arsitektur Medallion (Bronze -> Silver -> Gold)
class MedallionPipelineSimulator:
    def __init__(self):
        self.bronze_layer = []
        self.silver_layer = []
        self.gold_layer = {}

    # 1. Lapisan Bronze: Raw Ingestion (Append-only, simpan apa adanya)
    def ingest_to_bronze(self, raw_events):
        for ev in raw_events:
            record = ev.copy()
            record['_ingest_time'] = '2026-03-01T10:00:00Z'
            self.bronze_layer.append(record)

    # 2. Lapisan Silver: Cleansing, Deduplication, & Type Conformance
    def process_to_silver(self):
        seen_ids = set()
        for item in self.bronze_layer:
            tx_id = item.get('tx_id')
            # Validasi data: abaikan duplikat dan amount tidak valid (negatif)
            if tx_id not in seen_ids and item.get('amount', -1) > 0:
                seen_ids.add(tx_id)
                self.silver_layer.append({
                    'tx_id': int(tx_id),
                    'user_id': str(item['user_id']).strip().upper(),
                    'category': str(item['category']).capitalize(),
                    'amount': float(item['amount'])
                })

    # 3. Lapisan Gold: Agregasi Analitis Bisnis & Feature Engineering AI
    def process_to_gold(self):
        # Hitung total pengeluaran per kategori & rata-rata per transaksi
        summary = {}
        for row in self.silver_layer:
            cat = row['category']
            if cat not in summary:
                summary[cat] = {'total_sales': 0.0, 'tx_count': 0}
            summary[cat]['total_sales'] += row['amount']
            summary[cat]['tx_count'] += 1
        self.gold_layer = summary

# Ingestion 4 event mentah (termasuk anomali duplikasi ID 101 dan amount negatif)
raw_inputs = [
    {'tx_id': 101, 'user_id': 'u1 ', 'category': 'elektronik', 'amount': 250.0},
    {'tx_id': 101, 'user_id': 'u1 ', 'category': 'elektronik', 'amount': 250.0},  # Duplikat
    {'tx_id': 102, 'user_id': 'u2', 'category': 'fashion', 'amount': -50.0},     # Anomali negatif
    {'tx_id': 103, 'user_id': 'u3', 'category': 'elektronik', 'amount': 150.0}
]

pipe = MedallionPipelineSimulator()
pipe.ingest_to_bronze(raw_inputs)
pipe.process_to_silver()
pipe.process_to_gold()

print('Hasil Eksekusi Pipeline Arsitektur Medallion:')
print(f'  1. Lapisan Bronze (Raw Ingest)     : {len(pipe.bronze_layer)} event mentah tersimpan')
print(f'  2. Lapisan Silver (Clean & Dedupe) : {len(pipe.silver_layer)} baris terverifikasi (Duplikat & Anomali disaring)')
print(f'  3. Lapisan Gold (Business Metrics) :')
for cat, stats in pipe.gold_layer.items():
    print(f'     - Kategori {cat:11s}: Total=${stats["total_sales"]:6.2f} | Transaksi={stats["tx_count"]}')
print('  Kesimpulan: Data siap disajikan ke dasbor eksekutif dan feature store AI!')
